MATCH (a:PlantItem {tag: 'E-1403'}), (b:PlantItem {tag: 'EH-1401'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((n:PlantItem WHERE n.tag <> 'E-1404')-[:line_to]->()){1,} (b)
       } AS can_flow_without_E_1404

MATCH (item:PlantItem {tag: 'R-2901'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(:PlantItem)-[:send_signal_to*0..]->(f:ProcessInstrumentationFunction {loop_tag: 'PIC-17022'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'P-4902B'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
