MATCH (a:PlantItem {tag: 'H-5301'}), (b:PlantItem {tag: 'P-5301B'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE NONE(n IN nodes(p) WHERE n.tag = 'R-5301')
       } AS reachable_without_R-5301

MATCH (a:PlantItem {tag: 'H-5301'}), (b:PlantItem {tag: 'P-5301B'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE NONE(n IN nodes(p) WHERE n.tag = 'R-5301')
       } AS reachable_without_R_5301

MATCH (v:PlantItem:ButterflyValve {unit_id: '35'})
