ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'V-3601'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'E-3802'})-[:is_drawn_on]->(sheet:Sheet)
