RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem WHERE y.tag <> 'P-3901A'))+ (b)
       } AS reachable_without_P3901A

MATCH (acs:AirCoolingSystem {unit_id: '18'})
RETURN DISTINCT acs.tag AS tag
