MATCH (f:ProcessInstrumentationFunction {loop_tag: 'FSLL-31003'})-[:send_signal_to*1..]->(a:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-2603'}), (b:PlantItem {tag: 'E-2701'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (s:PlantItem {tag: 'TK-3903'}), (e:PlantItem {tag: 'F-4001A'}), (v:Valve)
WHERE EXISTS { (s)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'T-2401'}), (b:PlantItem {tag: 'E-2402'})
MATCH (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v.tag) AS valve_count

MATCH (a:PlantItem {tag: 'EH-5101'}), (b:PlantItem {tag: 'K-5401'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y.tag <> 'E-5201')* (b)
       } AS can_flow_without_E5201

MATCH (a:PlantItem {tag: 'H-2901'}), (b:PlantItem {tag: 'E-2901'}), (r:PlantItem {tag: 'R-2901'})
RETURN a.tag AS from_tag, b.tag AS to_tag
WHERE EXISTS {
  MATCH (a)-[:line_to]->((x:PlantItem WHERE x <> r)-[:line_to]->(y:PlantItem WHERE y <> r))*
  WHERE y = b
}

MATCH (a:PlantItem {tag: 'H-2901'}), (b:PlantItem {tag: 'E-2901'}), (r:PlantItem {tag: 'R-2901'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> r AND y <> r)+ (b)
}
RETURN b.tag AS tag

MATCH (a:PlantItem {tag: 'P-1901B'}), (b:PlantItem {tag: 'V-2201'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-2101A'}), (b:PlantItem {tag: 'P-2201B'}), (m:PlantItem {tag: 'M-2101'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y <> m)+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'P-3801B'}), (b:PlantItem {tag: 'D-4901'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (a:PlantItem {tag: 'F-301B'}), (b:PlantItem {tag: 'P-801A'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'XV-6013')+ (b)
} AS reachable_without_XV_6013

MATCH (a:PlantItem {tag: 'TK-3304'}), (b:PlantItem {tag: 'EA-5301'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y.tag <> 'P-4201C')+ (b)
       } AS reachable_without_P4201C

MATCH (a:PlantItem {tag: 'P-3801B'}), (b:PlantItem {tag: 'EH-5101'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'V-1601'}), (b:PlantItem {tag: 'E-4903'})
MATCH (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*0..]->(b) }
RETURN count(v) AS valve_count, collect(v.tag) AS valve_tags;

MATCH (a:PlantItem {tag: 'D-1801'}), (b:PlantItem {tag: 'E-1801'})
WHERE EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'LV-18063')+ (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag

MATCH (:PlantItem {tag: 'PI-11015'})-[:is_located_in]->(s:PlantSection)
RETURN DISTINCT s.unit_id AS unit_id
ORDER BY unit_id;

MATCH (:PlantItem {tag: 'XV-10029'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'E-2901'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (i:PlantItem {tag: 'H-1501'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (p:PlantItem {tag: 'P-3301A'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
  AND v.tag IS NOT NULL
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (:PlantItem {tag: 'P-4902A'})-[:line_to*1..]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-4201C'})-[:line_to*1..]->(v:Valve)
WHERE EXISTS {
  MATCH (v)-[:line_to*1..]->(:Equipment)
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag
